INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was versteht ein Fachinformatiker unter Benutzbarkeit?', 2, '[{"text": "Nutzerfreundlichkeit von Systemen", "correct": true, "because": "Einfache Bedienung"}, {"text": "Hardwareleistung", "correct": false, "because": "Kein direkter Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Benutzbarkeit als Fachinformatiker?', 3, '[{"text": "Effiziente und intuitive Nutzung", "correct": true, "because": "Verbessert User Experience"}, {"text": "Kosten senken", "correct": false, "because": "Indirekt"}, {"text": "Systemgeschwindigkeit erhöhen", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte gehören zur Benutzbarkeit?', 5, '[{"text": "Effektivität", "correct": true, "because": "Aufgaben erfolgreich erledigen"}, {"text": "Effizienz", "correct": true, "because": "Wenig Aufwand"}, {"text": "Hardwarewartung", "correct": false, "because": "Kein Usability-Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Benutzbarkeit beeinflusst die Nutzerzufriedenheit. b) Sie ist nur für Webseiten relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gilt für alle Systeme"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Planung von Benutzbarkeit?', 4, '[{"text": "Nutzeranforderungen", "correct": false, "because": "Kern der Planung"}, {"text": "Benutzerfreundlichkeit", "correct": false, "because": "Hauptziel"}, {"text": "Büroverschönerung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Benutzbarkeit mit Usability-Tests geprüft wird?', 2, '[{"text": "Ja", "correct": true, "because": "Überprüft Nutzerfreundlichkeit"}, {"text": "Nein", "correct": false, "because": "Standardmethode"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Standard ist für Benutzbarkeit relevant?', 3, '[{"text": "ISO 9241-11", "correct": true, "because": "Definiert Usability"}, {"text": "ISO 27001", "correct": false, "because": "IT-Sicherheit"}, {"text": "DIN EN 12464", "correct": false, "because": "Beleuchtung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Verbesserung der Benutzbarkeit?', 5, '[{"text": "Intuitive Navigation", "correct": true, "because": "Einfache Bedienung"}, {"text": "Klarer Feedback-Mechanismus", "correct": true, "because": "Nutzerinformation"}, {"text": "Hardwareleistung", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Benutzbarkeit reduziert Fehler. b) Sie ist nur für Endnutzer wichtig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Entwickler profitieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Benutzbarkeit unwichtig?', 4, '[{"text": "Benutzerfeedback", "correct": false, "because": "Verbesserungspotenzial"}, {"text": "Usability-Tests", "correct": false, "because": "Prüft Effizienz"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss Benutzbarkeit bei Softwareentwicklung berücksichtigt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Nutzerakzeptanz"}, {"text": "Nein", "correct": false, "because": "Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet hohe Benutzbarkeit?', 4, '[{"text": "Weniger Supportaufwand", "correct": true, "because": "Intuitive Nutzung"}, {"text": "Höhere Zufriedenheit", "correct": true, "because": "Bessere Erfahrung"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Benutzbarkeit nur Design betrifft. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Funktionalität"}, {"text": "Ja", "correct": false, "because": "Umfassender Ansatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Benutzbarkeit?', 3, '[{"text": "Nutzerfreundlichkeit", "correct": true, "because": "Hauptziel"}, {"text": "Kosten", "correct": false, "because": "Sekundär"}, {"text": "Ästhetik", "correct": false, "because": "Teil, aber nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Benutzbarkeit umfasst Effizienz. b) Sie ist nur für grafische Oberflächen relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch CLI-Systeme"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat schlechte Benutzbarkeit?', 5, '[{"text": "Höhere Fehlerrate", "correct": true, "because": "Unklare Bedienung"}, {"text": "Geringere Akzeptanz", "correct": true, "because": "Nutzerfrust"}, {"text": "Schnellere Entwicklung", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat ein Fachinformatiker bei der Benutzbarkeit?', 3, '[{"text": "Usability-Tests durchführen", "correct": true, "because": "Prüft Nutzerfreundlichkeit"}, {"text": "Büro reinigen", "correct": false, "because": "Kein Bezug"}, {"text": "Marketing betreiben", "correct": false, "because": "Andere Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Benutzbarkeit mit Tools getestet werden?', 2, '[{"text": "Ja", "correct": true, "because": "z.B. Eye-Tracking"}, {"text": "Nein", "correct": false, "because": "Testbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool könnte ein Fachinformatiker für Usability-Tests nutzen?', 4, '[{"text": "Hotjar", "correct": true, "because": "Heatmaps und Feedback"}, {"text": "Photoshop", "correct": false, "because": "Design, kein Test"}, {"text": "Excel", "correct": false, "because": "Tabellenkalkulation"}]');
